function toast(a,b){UI.toast.querySelector('b').textContent=a;UI.toast.querySelector('span').textContent=b;UI.toast.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>UI.toast.classList.remove('show'),1900)}
function pathPoint(progress){let dist=progress;for(let i=0;i<PATH.length-1;i++){let [ax,ay]=PATH[i],[bx,by]=PATH[i+1],len=Math.hypot(bx-ax,by-ay);if(dist<=len)return{x:ax+(bx-ax)*dist/len,y:ay+(by-ay)*dist/len};dist-=len}return{x:PATH.at(-1)[0],y:PATH.at(-1)[1]}}
const PATHLEN=PATH.slice(1).reduce((a,p,i)=>a+Math.hypot(p[0]-PATH[i][0],p[1]-PATH[i][1]),0);
function spawnEnemy(){if(!S.spawn.length)return;const type=S.spawn.shift();S.enemies.push(makeEnemy(type,S.enemies.length,S.enemies.length+S.spawn.length));}
function towerRange(t){return TYPES[t.type].range*(1+(t.level-1)*.16)}
function update(dt){S.elapsed+=dt;if(S.paused||S.over)return;const d=dt*S.speed;
 if(S.running){S.spawnTimer-=d;if(S.spawn.length&&S.spawnTimer<=0){spawnEnemy();S.spawnTimer=WAVE_DATA[S.wave].gap;}}
 for(const e of S.enemies){if(!e.alive)continue;e.flash=Math.max(0,e.flash-d*3);e.progress+=e.speed*d;e.segment=e.progress>PATHLEN?PATH.length-1:0;const p=pathPoint(e.progress);e.x=p.x;e.y=p.y;if(e.progress>=PATHLEN){e.alive=false;S.lives-=e.type==='core'?4:e.type==='brute'?2:1;S.particles.push({x:930,y:295,life:.8,max:.8,color:'#ff6677',n:10});if(S.lives<=0){S.lives=0;S.over=true;S.running=false;S.won=false;toast('CORE BREACHED','The sector fell. Regroup and try again.')}}}
 for(const t of S.towers){t.cool-=d;if(t.cool>0)continue;const spec=TYPES[t.type],r=towerRange(t);let target=null,best=-1;for(const e of S.enemies){if(!e.alive)continue;const hidden=(e.cloak&&S.flare<=0&&t.type!=='prism')||(e.burrow&&e.progress<PATHLEN*.79&&S.flare<=0);if(hidden)continue;const dist=Math.hypot(e.x-t.x,e.y-t.y);if(dist>r)continue;if(spec.targets.includes(e.type)&&e.progress>best){target=e;best=e.progress}}if(target){t.cool=spec.rate*(t.type==='pulse'&&target.type==='cloak'?.86:1);const dmg=spec.damage*(1+(t.level-1)*.28);if(t.type==='mortar'){for(const e of S.enemies)if(e.alive&&Math.hypot(e.x-target.x,e.y-target.y)<37)hit(e,dmg*.72)}else hit(target,dmg);S.bullets.push({x:t.x,y:t.y,tx:target.x,ty:target.y,life:.14,color:spec.color,type:t.type});}}
 for(const b of S.bullets)b.life-=d;S.bullets=S.bullets.filter(b=>b.life>0);for(const p of S.particles)p.life-=d;S.particles=S.particles.filter(p=>p.life>0);
 if(S.flare>0)S.flare-=d;if(S.flareCd>0)S.flareCd-=d;
 S.enemies=S.enemies.filter(e=>e.alive);if(S.running&&S.spawn.length===0&&S.enemies.length===0&&!S.over){S.running=false;S.cash+=35+S.wave*5;toast('WAVE CLEARED',`+${35+S.wave*5} salvage · lines hold`);S.wave++;if(S.wave>=WAVE_DATA.length){S.won=true;S.over=true;toast('SECTOR SECURED','All eight formations broken. Last light holds.')}}
 syncUI();}
function hit(e,dmg){let rest=dmg;if(e.shield>0){const n=Math.min(rest,e.shield);e.shield-=n;rest-=n}if(rest>0)e.hp-=Math.max(1,rest-e.armor);e.flash=.12;if(e.hp<=0){e.alive=false;S.cash+=e.reward;for(let i=0;i<4;i++)S.particles.push({x:e.x,y:e.y,life:.4+Math.random()*.25,max:.65,color:e.color,n:1,dx:(Math.random()-.5)*70,dy:(Math.random()-.5)*70})}}
function deploy(x,y){if(S.selectedTower){const t=S.selectedTower;const d=TYPES[t.type];const cost=Math.floor(d.cost*(.65+t.level*.28));if(t.level>=3||S.cash<cost)return;S.cash-=cost;t.level++;t.cool=Math.min(t.cool,.2);updateSelectedInfo();syncUI();toast('NODE UPGRADED',`${d.name} · level ${t.level}`);return}
 const type=S.selectedType,d=TYPES[type];if(S.cash<d.cost){toast('INSUFFICIENT SALVAGE',`${d.cost} required to deploy`);return}if(distancePath(x,y)<42){toast('ROUTE BLOCKED','Keep a safe distance from the hostile path.');return}if(S.towers.some(t=>Math.hypot(t.x-x,t.y-y)<29)){toast('GRID OCCUPIED','Deploy with a little more clearance.');return}S.cash-=d.cost;S.towers.push({x,y,type,level:1,cool:.1,phase:Math.random()*6});S.selectedTower=null;renderTowerCards();updateSelectedInfo();syncUI()}
