function screenToMap(ev){const r=canvas.getBoundingClientRect();return{x:(ev.clientX-r.left)/r.width*1000,y:(ev.clientY-r.top)/r.height*590}}
canvas.addEventListener('pointerdown',ev=>{ev.preventDefault();const p=screenToMap(ev);for(const t of [...S.towers].reverse())if(Math.hypot(t.x-p.x,t.y-p.y)<24){S.selectedTower=t;updateSelectedInfo();return}if(distancePath(p.x,p.y)<27){S.selectedTower=null;updateSelectedInfo();return}deploy(p.x,p.y)});
